use lg_rules::builtin::builtin_rules;
use lg_rules::{Engine, Rule};

#[test]
fn disc_l03() {
    let e = Engine::new(builtin_rules());
    assert_eq!(e.categorize("MERCADO LIVRE BR 9981"), Some("compras:online"));
    let e = Engine::new(vec![Rule::new("POSTO*", "a"), Rule::new("POSTO SHELL*", "b")]);
    assert_eq!(e.categorize("POSTO SHELL 1"), Some("b"));
}
